const T = api.t;
const C = { paper:'#F7F5F0', orange:'#E9853C', orangeDark:'#C96432', yellow:'#F7B84B', ink:'#34304A',
  blue:'#557AC5', blueLight:'#B9D2EA', paleBlue:'#DCEEF2', mint:'#67C9B5', mintDark:'#3FA98F',
  coral:'#FF5A4E', white:'#FFFDF8', grey:'#8C98A6', skin:'#F3B99F', cream:'#F1E3CC' };
const p = (at, dur) => TT.clamp01((T - at) / dur);
const pop = (at, dur) => Math.max(0, TT.ease.back(1.70158)(p(at, dur === undefined ? 0.5 : dur)));
const circle = (x, y, r, c) => { if (r <= 0.3) return; ctx.fillStyle = c; ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill(); };
const rr = (x, y, w, h, rad, c) => { if (w <= 0.5 || h <= 0.5) return; ctx.fillStyle = c; ctx.beginPath(); ctx.roundRect(x, y, w, h, Math.max(0, Math.min(rad, Math.abs(w) / 2, Math.abs(h) / 2))); ctx.fill(); };
const stroke = (pts, c, w) => { ctx.strokeStyle = c; ctx.lineWidth = w === undefined ? 6 : w; ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.beginPath(); pts.forEach((pt, i) => i ? ctx.lineTo(pt[0], pt[1]) : ctx.moveTo(pt[0], pt[1])); ctx.stroke(); };
const txt = (s, x, y, size, col, font, align) => TT.text(ctx, s, x, y, size, { fontKey: font || 'sans-700', color: col || C.ink, align: align || 'left', baseline: 'middle' });
const partial = (pts, k, col, w) => {
  let total = 0; const segs = [];
  for (let i = 1; i < pts.length; i += 1) {
    const L = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);
    segs.push(L); total += L;
  }
  let want = total * TT.clamp01(k);
  let hx = pts[0][0], hy = pts[0][1];
  ctx.strokeStyle = col; ctx.lineWidth = w === undefined ? 6 : w; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  ctx.beginPath(); ctx.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i += 1) {
    const L = segs[i - 1];
    if (want >= L) { ctx.lineTo(pts[i][0], pts[i][1]); hx = pts[i][0]; hy = pts[i][1]; want -= L; }
    else {
      const f = L > 0 ? want / L : 0;
      hx = pts[i - 1][0] + (pts[i][0] - pts[i - 1][0]) * f;
      hy = pts[i - 1][1] + (pts[i][1] - pts[i - 1][1]) * f;
      ctx.lineTo(hx, hy); break;
    }
  }
  ctx.stroke();
  return [hx, hy];
};

